import React from "react";
import { getCurrentUser } from "../helpers/auth";
import AnimationRevealPage from "helpers/AnimationRevealPage";
import BGMHero from "components/hero/BGMHero";
import Features from "components/features/VerticalWithAlternateImageAndText.js";
import Testimonial from "components/testimonials/TwoColumnWithImage.js";
import Footer from "components/footers/SimpleFiveColumn.js";
import Leaderboard from "pages/Leaderboard.js";
import RegistrationSteps from "components/steps/RegistrationSteps";

export default function BGMLandingPage() {
  const user = getCurrentUser();
  return (
    <AnimationRevealPage>
      {user && (
        <div style={{background: '#e6ffed', color: '#155724', padding: '1rem', textAlign: 'center', fontWeight: 'bold'}}>
          Welcome, {user.name}!
        </div>
      )}
      <BGMHero />
      <RegistrationSteps />
      <Features />
      <Testimonial />
      <Leaderboard />
      <Footer />
    </AnimationRevealPage>
  );
}
